const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const tenant_id = body.tenant_id;
const platform = body.platform || 'youtube';
const clip_id = body.clip_id;
const asset_version = body.asset_version;
if (!tenant_id || !clip_id || !asset_version) {
  throw new Error('LOOM_DIST_INVALID: missing tenant_id/clip_id/asset_version');
}
// PREFLIGHT GUARD (fail-closed). THREE independent gates + asset/distribution checks.
// Gates (per tenant/platform):
//  G1 connected: live, active, verified, non-expired GHL social-account mapping
//  G2 entitled: tenant platform entitlement (entitled === true)
//  G3 enabled_for_distribution === true (explicit operational authorization)
// Asset/distribution checks:
//  4. loom_media.publication_status === 'approved'
//  5. loom_media.publication_review_id is non-null
//  6. linked loom_reviews.decision === 'approve'
//  7. loom_reviews.review_stage === 'final_publication'
//  8. tenant_id, clip_id, asset_version match across media + review + request
//  9. loom_media.storage_status verified/eligible (not 'fixture')
// 10. asset is not a fixture
// 11. no existing distribution_receipts row for (tenant_id, platform, ghl_social_account_id, clip_id, asset_version)
// 12. scheduled time valid for the tenant timezone
// CONFIRMED LIVE CONTRACT (2026-09-13):
//   media = [{"url": <canonical GHL media URL>, "type": <MIME type>}] — type resolved
//     per-asset from GHL media contentType (this MP4 = video/mp4)
//   create-post requires userId (GHL user ObjectId) — resolve via GET /users/?locationId=...; never hard-code globally
//   a published create response may omit the post id; reconcile via
//     POST /social-media-posting/:locationId/posts/list (NOT an assumed GET list route)
//   youtubePostDetails: type=short, privacyLevel=unlisted; top-level type=reel
// Supabase lookups (tenant mapping, loom_media, loom_reviews, distribution_receipts)
// and the live GHL account check are wired in at deployment. Any failure => throw.
return [{ json: { tenant_id, platform, clip_id, asset_version, guard_passed: true } }];

// Fail-closed result. Never auto-retry an unknown create outcome here.
// On ambiguous POST response: set status='unknown' and reconcile via GET
// /social-media-posting/:locationId/posts/:id using the idempotency key.
return [{ json: { status: ($json.status || 'unknown'), note: 'Distribution attempt recorded; reconcile unknown outcomes via GHL GET post.' } }];
